import * as T from 'three'; import { palette as P, wardrobes, type Archetype } from './palette'; import { sphere, torus, bake, mats, thinLine, type Material } from './assets'; import { painted, tone as toneLight } from './tone'; import { skullGeometry, ringGeometry, garmentGeometry, ringSurface, ribbonGeometry, blockGeometry, bootFoot, BOOT_SPEC, handGeometry, lockGeometry, shellGeometry, shineGeometry, hairStyles, HAND_STATES, type HandState, type BootFamily, type Surface } from './character-kit'; const ramp = new T.DataTexture(new Uint8Array([128, 202, 255]), 3, 1, T.RedFormat); ramp.minFilter = ramp.magFilter = T.NearestFilter; ramp.generateMipmaps = false; ramp.needsUpdate = true; const skinColors = P.skin; const skin = skinColors.map(toon); const hair = P.hair.map(toon); for(const m of [...skin,...hair])m.userData.plain=true; const boot = toon(P.neutral.ink), brass = toon(P.metal.brass), ivory = toon(P.neutral.paper); brass.userData.plain=true; /** Worn cloth: side seams, stitched hems, hatching and grime, inked by hand. u wraps * the body (0 = centre front), v runs along each tailored piece. */ const coloredToon = new T.MeshToonMaterial({ vertexColors:true, gradientMap:ramp, map:clothMap() }); const wardrobePhase={value:0}; coloredToon.onBeforeCompile=wardrobeHook; coloredToon.customProgramCacheKey=()=> 'terra-wardrobe-colors'; painted(coloredToon);thinLine(coloredToon); // Hair, skin and metal share the wardrobe shader but not the stitched cloth texture. const plainToon=new T.MeshToonMaterial({vertexColors:true,gradientMap:ramp}); plainToon.onBeforeCompile=wardrobeHook;plainToon.customProgramCacheKey=()=> 'terra-wardrobe-plain';painted(plainToon);thinLine(plainToon); const wardrobeMaterials=new Map<string,T.MeshToonMaterial>(); export const expressions=['neutral','happy','tired','focused','annoyed','blink','surprised'] as const; // Elliptical rings make a continuous tailored silhouette instead of stacked boxes. // One atlas per skin tone: five eye families (r