abs(v - d.y) / .13), 2.); b += d.x * tri * smoothstep(.22, .55, t) * (1. - smoothstep(.88, 1.02, t)); // cheek triangle b -= .12 * smoothstep(.62, .8, v) * smoothstep(.3, .7, t); // brow and temple stay lit longer if (ft == 2) b += .22 * smoothstep(.2, .05, v) * smoothstep(.2, .5, t); // sharp: jaw shadow reaches under the chin float w = max(fwidth(u) * 1.2 * d.z, .004); faceLit = smoothstep(b - w, b + w, u); // Nose shadow on the far side of the nose, widest at its base. float nb = clamp((.405 - v) / .1, 0., 1.), nose = step(.3, v) * step(v, .405) * step(-.015 - nb * d.w, u) * step(u, -.012); faceLit *= 1. - nose * smoothstep(.12, .3, t) * (1. - smoothstep(.8, .95, t)); // Sun height: high light shades the chin band and under the nose; light from below shades the brow. float hi = smoothstep(.45, .9, elev), lo = smoothstep(-.1, -.5, elev), wv = max(fwidth(v) * 1.2, .004); faceLit *= 1. - hi * (1. - smoothstep(mix(.02, .14, hi) - wv, mix(.02, .14, hi) + wv, v)); faceLit *= 1. - hi * step(.29, v) * step(v, .33) * step(abs(u), .06); faceLit *= 1. - lo * smoothstep(.55 - wv, .55 + wv, v); // Tired faces carry a soft under-eye band whenever the face is lit. if (ft == 3) faceLit *= 1. - .6 * step(.415, v) * step(v, .44) * step(.18, abs(vFaceP.x / .17)) * step(abs(vFaceP.x / .17), .75); } `; /** Modern anime face construction (2020s TV/game style): large almond eyes set low, heavy * outer upper lash with a wing, tall iris with lash shadow and two catchlights, only a sliver * of white; tiny nose tick and mouth; hard hair shadow across the forehead; hatched blush. */ const faces=skinColors.map(tone=>{ const canvas=document.createElement('canvas');canvas.width=1792;canvas.height=256*FACE_TYPES;const c=canvas.getContext('2d')!; const irises=[['#2c4f86','#6fa6d8'],['#5a3322','#c0874a'],['#1f5f58','#63b3a3'],['#4b2f6e','#a07ac8'],['#6a4a1c','#d8a94a']]; const lineInk='#23161b',shade=shadeOf(tone,.8); for(let type=0;type<FACE_TYPES;type++)for(let state=0;state<7;state++){ c.save(