y0+5);c.closePath();c.fill(); } // Nose: a single small shadow tick. Mouth: small and close under it. c.strokeStyle='rgba(150,86,78,.7)';c.lineWidth=3.5;c.beginPath();c.moveTo(258,366);c.lineTo(252,377);c.stroke(); c.strokeStyle='#6a2f36';c.lineWidth=4;c.beginPath(); if(surprised){c.fillStyle='#6c3b45';c.ellipse(256,412,7,10,0,0,Math.PI*2);c.fill();} else if(pleasant){c.fillStyle='#7a3240';c.moveTo(242,404);c.quadraticCurveTo(256,422,270,404);c.closePath();c.fill();} else if(annoyed){c.moveTo(246,412);c.quadraticCurveTo(256,406,266,412);c.stroke();} else if(focused){c.moveTo(248,410);c.lineTo(264,410);c.stroke();} else if(tiredS){c.moveTo(246,412);c.quadraticCurveTo(256,409,266,412);c.stroke();} else{c.moveTo(247,408);c.quadraticCurveTo(256,412,265,408);c.stroke();} c.restore(); } const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;map.generateMipmaps=true;map.minFilter=T.LinearMipmapLinearFilter;map.anisotropy=8; const m=new T.MeshToonMaterial({map,gradientMap:ramp,emissive:P.neutral.paper,emissiveMap:map,emissiveIntensity:.12}); m.userData.faceAtlas=true; (m as unknown as {defines:Record<string,string>}).defines={TOON:'',TERRA_FACE:''}; m.onBeforeCompile=shader=>{ shader.vertexShader=shader.vertexShader.replace('#include <color_vertex>','#include <color_vertex>
